//! Unicode character properties for shaping (tables generated by
//! scripts/gen_unicode_props.py) and grapheme clusters as HarfBuzz forms
//! them.

const std = @import("std");
const data = @import("unicode_props_data.zig");

fn inRanges(ranges: []const [2]u21, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (cp < ranges[mid][0]) {
            hi = mid;
        } else if (cp > ranges[mid][1]) {
            lo = mid + 1;
        } else return true;
    }
    return false;
}

/// General_Category Mn, Mc or Me.
pub fn isMark(cp: u21) bool {
    return cp >= 0x300 and inRanges(&data.mark_ranges, cp);
}

/// General_Category Mn.
pub fn isNonspacingMark(cp: u21) bool {
    return cp >= 0x300 and inRanges(&data.nonspacing_mark_ranges, cp);
}

/// General_Category L*.
pub fn isLetter(cp: u21) bool {
    if (cp < 0x80) return (cp | 0x20) >= 'a' and (cp | 0x20) <= 'z';
    return inRanges(&data.letter_ranges, cp);
}

/// General_Category is Cf, Cn, Co, Cs, L* or M* (HarfBuzz's FORMAT ..
/// NON_SPACING_MARK range): the character continues a word.
pub fn isWordChar(cp: u21) bool {
    return !inRanges(&data.non_word_ranges, cp);
}

/// The script a character gives a run, as HarfBuzz's
/// guess_segment_properties reads it: none for Common, Inherited and
/// unassigned characters.
pub const RunScript = enum { none, devanagari, other };

pub fn runScript(cp: u21) RunScript {
    if (!inRanges(&data.strong_script_ranges, cp)) return .none;
    return if (inRanges(&data.devanagari_script_ranges, cp)) .devanagari else .other;
}

pub fn isExtendedPictographic(cp: u21) bool {
    return cp >= 0xA9 and inRanges(&data.ext_pict_ranges, cp);
}

fn isRegionalIndicator(cp: u21) bool {
    return cp >= 0x1F1E6 and cp <= 0x1F1FF;
}

/// The canonical single-step decomposition of `cp`: (first, second), the
/// second 0 for a singleton (U+212B -> U+00C5). Null if it has none.
pub fn decomposeOnce(cp: u21) ?[2]u21 {
    if (cp < 0xC0) return null;
    const table = &data.decompositions;
    var lo: usize = 0;
    var hi: usize = table.len;
    while (lo < hi) {
        const mid = (lo + hi) / 2;
        if (cp < table[mid][0]) {
            hi = mid;
        } else if (cp > table[mid][0]) {
            lo = mid + 1;
        } else return .{ table[mid][1], table[mid][2] };
    }
    return null;
}

/// HarfBuzz's space fallback (hb_unicode_funcs_t::space_t): a space
/// character the font lacks is drawn as its space glyph, this wide. The
/// em fractions are the enum value (an em divided by it).
pub const SpaceFallback = enum(u8) {
    none = 0,
    em = 1,
    em_2 = 2,
    em_3 = 3,
    em_4 = 4,
    em_5 = 5,
    em_6 = 6,
    em_16 = 16,
    four_em_18,
    space,
    figure,
    punctuation,
    narrow,

    pub fn of(cp: u21) SpaceFallback {
        return switch (cp) {
            0x0020, 0x00A0 => .space,
            0x2000, 0x2002 => .em_2,
            0x2001, 0x2003, 0x3000 => .em,
            0x2004 => .em_3,
            0x2005 => .em_4,
            0x2006 => .em_6,
            0x2007 => .figure,
            0x2008 => .punctuation,
            0x2009 => .em_5,
            0x200A => .em_16,
            0x202F => .narrow,
            0x205F => .four_em_18,
            else => .none,
        };
    }
};

/// Sets `cont[i]` when code point i continues the grapheme of the one
/// before it, by HarfBuzz's rules (hb_set_unicode_props): marks, emoji
/// modifiers, the second of a regional indicator pair, ZWJ and an
/// Extended_Pictographic character after it, the halfwidth katakana
/// voiced marks, and tag characters. `cont` is as long as `cps`.
pub fn markContinuations(cps: []const u21, cont: []bool) void {
    var i: usize = 0;
    while (i < cps.len) : (i += 1) {
        const cp = cps[i];
        cont[i] = isMark(cp);
        if (cp >= 0x1F3FB and cp <= 0x1F3FF) {
            cont[i] = true;
        } else if (i > 0 and isRegionalIndicator(cp)) {
            if (isRegionalIndicator(cps[i - 1]) and !cont[i - 1]) cont[i] = true;
        } else if (cp == 0x200D) {
            cont[i] = true;
            if (i + 1 < cps.len and isExtendedPictographic(cps[i + 1])) {
                i += 1;
                cont[i] = true;
            }
        } else if ((cp >= 0xFF9E and cp <= 0xFF9F) or (cp >= 0xE0020 and cp <= 0xE007F)) {
            cont[i] = true;
        }
    }
}

const testing = std.testing;

test "isMark: nonspacing, spacing and enclosing marks" {
    try testing.expect(isMark(0x0301)); // combining acute (Mn)
    try testing.expect(isMark(0x093F)); // Devanagari vowel sign i (Mc)
    try testing.expect(isMark(0x20DD)); // combining enclosing circle (Me)
    try testing.expect(isMark(0xFE0F)); // variation selector (Mn)
    try testing.expect(!isMark('a'));
    try testing.expect(!isMark(0x0915)); // Devanagari ka
    try testing.expect(!isMark(0x200D)); // ZWJ is Cf
    try testing.expect(isNonspacingMark(0x0902)); // Devanagari anusvara (Mn, ccc 0)
    try testing.expect(!isNonspacingMark(0x093F)); // Mc
}

test "markContinuations follows HarfBuzz's grapheme rules" {
    const cps = [_]u21{ 'e', 0x0301, 0x1F1F8, 0x1F1EA, 0x1F1FA, 0x1F468, 0x200D, 0x1F469, 0x1F44D, 0x1F3FD, 0x0915, 0x093F };
    var cont: [cps.len]bool = undefined;
    markContinuations(&cps, &cont);
    // e acute | SE flag pair, then a lone U | man ZWJ woman | thumbs + tone | ka + i
    try testing.expectEqualSlices(bool, &.{ false, true, false, true, false, false, true, true, false, true, false, true }, &cont);
}

test "decomposeOnce: pairs, singletons, exclusions" {
    try testing.expectEqual([2]u21{ 'e', 0x0301 }, decomposeOnce(0x00E9).?);
    try testing.expectEqual([2]u21{ 0x00C5, 0 }, decomposeOnce(0x212B).?); // Angstrom sign
    try testing.expectEqual([2]u21{ 0x0915, 0x093C }, decomposeOnce(0x0958).?); // qa (excluded from composition)
    try testing.expectEqual([2]u21{ 0x0113, 0x0301 }, decomposeOnce(0x1E17).?); // e macron acute
    try testing.expect(decomposeOnce('a') == null);
    try testing.expect(decomposeOnce(0xAC00) == null); // Hangul is algorithmic
}

test "isLetter, isWordChar" {
    try testing.expect(isLetter('Q') and isLetter(0x0915) and isLetter(0x00E9));
    try testing.expect(!isLetter('5') and !isLetter(' ') and !isLetter(0x093F));
    try testing.expect(isWordChar(0x0915) and isWordChar(0x093F) and isWordChar(0x200D) and isWordChar(0xE000));
    try testing.expect(!isWordChar(' ') and !isWordChar('.') and !isWordChar('5') and !isWordChar(0x0964));
}

test "runScript: Devanagari, other scripts, and characters of none" {
    try testing.expectEqual(RunScript.devanagari, runScript(0x0915));
    try testing.expectEqual(RunScript.devanagari, runScript(0x093F)); // matra
    try testing.expectEqual(RunScript.none, runScript(0x0951)); // stress sign: Inherited
    try testing.expectEqual(RunScript.none, runScript(0x0964)); // danda: Common
    try testing.expectEqual(RunScript.none, runScript('5'));
    try testing.expectEqual(RunScript.other, runScript('a'));
}
